        position_id = uuid4(); user_id = uuid4(); account_id = uuid4(); position = ManagedPositionResponse(id=position_id, user_id=user_id, account_id=account_id, asset_identifier='AAPL', quantity=Decimal('100.500000'), cost_basis=Decimal('150.25'), acquisition_date=date(2024, 1, 15), status=PositionStatus.ACTIVE, currency='USD', created_at=datetime.now(), updated_at=datetime.now()); assert position.asset_identifier == 'AAPL'; assert position.quantity == Decimal('100.500000'); assert position.status == PositionStatus.ACTIVE; _m1_position = ManagedPositionResponse(id=uuid4(), user_id=uuid4(), account_id=uuid4(), asset_identifier='GOOGL', quantity=Decimal('50'), cost_basis=Decimal('100'), acquisition_date=date(2024, 1, 1), disposal_date=date(2024, 12, 31), status=PositionStatus.DISPOSED, currency='USD', position_metadata={'notes': 'test'}, account_name='Trading Account', created_at=datetime.now(), updated_at=datetime.now()); assert _m1_position.disposal_date == date(2024, 12, 31); assert _m1_position.position_metadata == {'notes': 'test'}; assert _m1_position.account_name == 'Trading Account'; _m2_response = ReconcilePositionsResponse(message='Reconciliation complete', created=5, updated=3, disposed=1); assert _m2_response.message == 'Reconciliation complete'; assert _m2_response.created == 5; assert _m2_response.updated == 3; assert _m2_response.disposed == 1; assert _m2_response.skipped == 0; assert _m2_response.skipped_assets == []; _m3_response = ReconcilePositionsResponse(message='Partial reconciliation', created=2, updated=1, disposed=0, skipped=3, skipped_assets=['UNKNOWN1', 'UNKNOWN2', 'UNKNOWN3']); assert _m3_response.skipped == 3; assert len(_m3_response.skipped_assets) == 3
        with pytest.raises(ValidationError): ReconcilePositionsResponse(message='Invalid', created=-1, updated=0, disposed=0)
        _m5_payload = ManualValuationSnapshotCreate(component_type='rsu', as_of_date=date(2025, 3, 31), value=Decimal('1000.00'), currency='usd', source='Employer RSU'); assert _m5_payload.currency == 'USD'; _m6_with_currency = ManualValuationSnapshotUpdate(currency='sgd'); _m6_without_currency = ManualValuationSnapshotUpdate(currency=None); assert _m6_with_currency.currency == 'SGD'; assert _m6_without_currency.currency is None; _m7_position_id = uuid4(); _m7_response = DepreciationResponse(position_id=_m7_position_id, asset_identifier='EQUIPMENT-001', period_depreciation=Decimal('1000.00'), accumulated_depreciation=Decimal('5000.00'), book_value=Decimal('15000.00'), method='straight_line', useful_life_years=10, salvage_value=Decimal('2000.00')); assert _m7_response.position_id == _m7_position_id; assert _m7_response.method == 'straight_line'; assert _m7_response.useful_life_years == 10
